_THEMES_META = {'themes': {}}
_SYSTEM_JSON = {'base': 'dark', 'label': 'System', 'tokens': {}}

def ensure_default_themes(base_path: str=None) -> None:
    """
    AppConfigs/themes/ klasöründe eksik olan varsayılan tema dosyalarını oluşturur.

    Oluşturulan dosyalar:
    - dark.qss
    - light.qss
    - themes_meta.json
    - system.json

    Args:
        base_path: Uygulamanın çalıştığı kök dizin. None ise os.getcwd() kullanılır.
    """
    if base_path is None:
        base_path = os.getcwd()
    themes_dir = os.path.join(base_path, 'AppConfigs', 'themes')
    try:
        os.makedirs(themes_dir, exist_ok=True)
    except Exception as e:
        app_logger.error(tr_log('core.theme_defaultCreate', 527, f'Tema klasörü oluşturulamadı: {e}'))
        return
    _write_if_missing(themes_dir, 'dark.qss', _DARK_QSS, encoding='utf-8')
    _write_if_missing(themes_dir, 'light.qss', _LIGHT_QSS, encoding='utf-8')
    meta_path = os.path.join(themes_dir, 'themes_meta.json')
    if not os.path.exists(meta_path):
        try:
            with open(meta_path, 'w', encoding='utf-8') as f:
                json.dump(_THEMES_META, f, indent=2, ensure_ascii=False)
            app_logger.info(tr_log('core.theme_defaultCreate', 542, 'Tema metadata dosyası oluşturuldu: themes_meta.json'))
        except Exception as e:
            app_logger.error(tr_log('core.theme_defaultCreate', 544, f'themes_meta.json oluşturulamadı: {e}'))
    system_path = os.path.join(themes_dir, 'system.json')
    if not os.path.exists(system_path):
        try:
            with open(system_path, 'w', encoding='utf-8') as f:
                json.dump(_SYSTEM_JSON, f, indent=2, ensure_ascii=False)
            app_logger.info(tr_log('core.theme_defaultCreate', 552, 'Sistem tema JSON dosyası oluşturuldu: system.json'))
        except Exception as e:
            app_logger.error(tr_log('core.theme_defaultCreate', 554, f'system.json oluşturulamadı: {e}'))

def _write_if_missing(directory: str, filename: str, content: str, encoding: str='utf-8') -> None:
    """Dosya mevcut değilse yazar, mevcutsa dokunmaz."""
    path = os.path.join(directory, filename)
    if not os.path.exists(path):
        try:
            with open(path, 'w', encoding=encoding) as f:
                f.write(content)
            app_logger.info(tr_log('core.theme_defaultCreate', 564, f'Varsayılan tema dosyası oluşturuldu: {filename}'))
        except Exception as e:
            app_logger.error(tr_log('core.theme_defaultCreate', 566, f'{filename} oluşturulamadı: {e}'))